function slugTitle(s:string){return s.split('-').map(x=>x?x[0].toUpperCase()+x.slice(1):x).join(' ')}
function fallback(slug:string):P{return p(slugTitle(slug),'Feature workspace from the DISH portal specification.','table',['Open','Pending','Completed','Exceptions'],['18','7','42','2'],['Reference','Subject','Updated','State'],[[`${slug.slice(0,3).toUpperCase()}-001`,'Primary record','Today','Open'],[`${slug.slice(0,3).toUpperCase()}-002`,'Secondary record','Yesterday','Pending']],['Open','Review','Export'],'Dedicated route; this fallback is only for a route not present in the documented menu.')}
export default function RolePortalScreen({role,slug}:{role:string;slug:string}){const profile=(A[role]||{})[slug]||fallback(slug);const [toast,setToast]=useState('');const [query,setQuery]=useState('');const flash=(x:string)=>{setToast(x);setTimeout(()=>setToast(''),1600)};const rows=profile.rows.filter(r=>r.join(' ').toLowerCase().includes(query.toLowerCase()));return <div className="moduleScreen"><div className="moduleHero"><div><div className="eyebrow">{role.toUpperCase()} · {profile.view.toUpperCase()}</div><h1>{profile.title}</h1><p className="subtitle">{profile.sub}</p></div><div className="actions"><button className="btn" onClick={()=>flash('Workspace refreshed')}><RefreshCcw size={15}/> Refresh</button><button className="btn" onClick={()=>flash('Export prepared')}><Download size={15}/> Export</button><button className="btn primary" onClick={()=>flash(`${profile.actions[0]} started`)}><Plus size={15}/> {profile.actions[0]}</button></div></div><div className="metricGrid">{profile.kpis.map((k,i)=><div className="card metric" key={k}><div className="metricLabel">{k}</div><div className="metricValue">{profile.values[i]}</div><div className="delta">Screen-specific metric</div></div>)}</div>{profile.view==='chart'&&<section className="section"><div className="sectionHead"><div><div className="eyebrow">ANALYTICS</div><h2>{profile.title} trend</h2></div><BarChart3 size={20}/></div><div className="chartArea">{profile.rows.map((r,i)=><div className="chartRow" key={i}><span>{r[0]}</span><div className="bar"><i style={{width:`${35+(i*17)%55}%`}}/></div><strong>{r[1]}</strong></div>)}</div></section>}{profile.view==='timeline'&&<section className="section"><div className="sectionHead"><div><div className="eyebrow">LIFECYCLE</div><h2>Workflow timeline</h2></div></div><div className="timeline">{profile.rows.map((r,i)=><div className="timelineItem" key={i}><span className="dot"/><div><strong>{r[0]}</strong><p>{r.slice(1).join(' · ')}</p></div></div>)}</div></section>}<section className="section"><div className="sectionHead"><div><div className="eyebrow">WORKSPACE</div><h2>{profile.title} records</h2></div><div className="filterBar show"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search this screen"/><Filter size={15}/></div></div><div className="tableWrap"><div className="record tableHeader"><span className="recordMain"><strong>{profile.columns.join(' · ')}</strong></span></div>{rows.map((r,i)=><div className="record" key={i}><span className="recordMain"><strong>{r[0]}</strong><span>{r.slice(1,-1).join(' · ')}</span></span><span className="recordMeta"><span className="status">{r[r.length-1]}</span></span></div>)}</div></section><div className="dashboardGrid"><div className="card largeCard"><div className="eyebrow">ACTIONS</div><h2>Workflow controls</h2><div className="quickList">{profile.actions.map(a=><button className="quick" key={a} onClick={()=>flash(`${a} completed for ${profile.title}`)}><span>{a}</span><ArrowLeftRight size={15}/></button>)}</div></div><div className="card largeCard"><div className="eyebrow">SCREEN RULE</div><h2>{profile.title}</h2><p className="muted">{profile.note}</p><div className="iconLine"><ShieldCheck size={16}/> Actions are represented as interactive frontend workflow controls.</div></div></div>{toast&&<div className="toast"><CheckCircle2 size={16}/>{toast}</div>}</div>}
